#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8

# Values live only in this process: never .env, never a file (ADR-0019 tier 4).
ENV_FILE=/dev/null
HARNESS_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$HARNESS_ROOT"

die() { printf '\n'; warn "$1"; exit 1; }

if [[ -n "${CLAUDECODE:-}" || ! -t 0 ]]; then
  die "Run this wizard yourself in a terminal outside any agent session (docs/agents/data-safety.md)."
fi

# ask_value VAR "Prompt" CURRENT SECRET: like ask/ask_secret, but the default is
# the note's current value rather than a .env line.
ask_value() {
  local key="$1" prompt="$2" current="$3" secret="$4" input="" hint=""
  [[ -n "$current" ]] && hint=" ${DIM}[Enter keeps current]${RESET}"
  printf '  %s%s%s%s ' "$BOLD" "$prompt" "$RESET" "$hint"
  if [[ "$secret" == yes ]]; then read -rs input || true; printf '\n'; else read -r input || true; fi
  [[ -z "$input" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# map_get / map_set read and write one input in $MAP. The map and values go to
# a JSON encoder over pipes (printf is a builtin): a process's environment is
# readable by same-user processes, and bash 3.2 here-strings use temp files.
# Only the W/C/K names travel in env.
map_get() {
  printf '%s' "$MAP" | W="$1" C="$2" K="$3" node -e '
    const m = JSON.parse(require("fs").readFileSync(0, "utf8")), e = process.env;
    process.stdout.write(m[e.W]?.[e.C]?.[e.K] ?? "");'
}
map_set() {
  MAP=$(printf '%s' "$MAP" | W="$1" C="$2" K="$3" node -e '
    const fs = require("fs"), e = process.env;
    const m = JSON.parse(fs.readFileSync(0, "utf8"));
    ((m[e.W] ??= {})[e.C] ??= {})[e.K] = fs.readFileSync(3, "utf8");
    process.stdout.write(JSON.stringify(m));' 3< <(printf '%s' "$4"))
}

hint_for() {
  case "$1/$2" in
    household-finance/SUPABASE_ACCESS_TOKEN) note "Supabase → Account → Access Tokens. A new token replaces the stored one; that's fine." ;;
    household-finance/database_password) note "From your Bitwarden item for the household-finance database. It must match the project's real password." ;;
    household-finance/supabase_organization_id) note "Supabase → Organization → Settings → the organization slug." ;;
    household-finance/site_url) note "The HTTPS origin the app will be served from (household-finance docs/hosted-supabase.md, step 1)." ;;
    household-finance/tailnet_site_url) note "https://<mac>.<tailnet>.ts.net, from tailscale status." ;;
    *) note "Find it in the custody that workspace's project docs name; HCP can't show a stored value." ;;
  esac
}

banner "HCP project inputs → Bitwarden note"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Prerequisites"
for tool in bw node terraform jq; do
  command -v "$tool" >/dev/null 2>&1 || die "$tool isn't installed."
done
[[ -d node_modules ]] || die "Run pnpm install in the harness first."
bw_status=$(bw status | jq -r .status)
[[ "$bw_status" == unauthenticated ]] && die "Log in first in this terminal: bw login"
UNLOCKED_HERE=no
if [[ "$bw_status" != unlocked || -z "${BW_SESSION:-}" ]]; then
  step "Unlocking Bitwarden for this run; the wizard locks it again when it exits."
  BW_SESSION=$(bw unlock --raw) || die "Bitwarden didn't unlock."
  export BW_SESSION
  UNLOCKED_HERE=yes
  # The session key stays valid until bw lock, so lock on every exit, Ctrl-C included.
  trap 'bw lock >/dev/null 2>&1' EXIT
fi
bw sync >/dev/null || warn "bw sync failed; continuing with the local vault copy."
step "Bitwarden is unlocked and synced."
say ""
ask_value TF_ORG "HCP Terraform organization name:" "${TF_VAR_tfe_organization:-}" no
[[ "$TF_ORG" =~ ^[A-Za-z0-9_-]+$ ]] || die "Use the organization name only: letters, numbers, - or _."
if [[ -n "${TF_TOKEN_app_terraform_io:-}" ]] || grep -qs '"app.terraform.io"' "$HOME/.terraform.d/credentials.tfrc.json"; then
  step "Using your existing Terraform login for app.terraform.io."
else
  open_url "https://app.terraform.io/app/settings/tokens"
  step "Create a user API token (Account settings → Tokens), or Ctrl-C and run terraform login."
  ask_value TF_TOKEN_app_terraform_io "Paste the HCP token (hidden):" "" yes
  [[ -n "$TF_TOKEN_app_terraform_io" ]] || die "The token is empty."
  export TF_TOKEN_app_terraform_io
fi
# Never TFE_TOKEN: hcp:projects would store that as platform-bootstrap's provider credential.
unset TFE_TOKEN
export TF_CLOUD_ORGANIZATION="$TF_ORG" TF_VAR_tfe_organization="$TF_ORG"
pause "Press Enter for stage 2."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Inputs platform-bootstrap manages"
say "Reading Terraform state addresses: input names only, never values."
terraform -chdir=infrastructure/hcp init -input=false >/dev/null || die "terraform init failed; check the organization and token."
state=$(terraform -chdir=infrastructure/hcp state list) || die "terraform state list failed."
MANAGED=$(node -e '
  const out = [];
  for (const line of require("fs").readFileSync(0, "utf8").split("\n")) {
    const m = /^tfe_variable\.project_input\["(\[.*\])"\]$/.exec(line.trim());
    if (m) out.push(JSON.parse(m[1].replaceAll("\\\"", "\"")).join(" "));
  }
  process.stdout.write(out.sort().join("\n"));' <<<"$state")
if [[ -n "$MANAGED" ]]; then
  while read -r w c k; do step "$w  $c  $k"; done <<<"$MANAGED"
else
  warn "platform-bootstrap manages no project inputs yet: the map starts empty."
fi
pause "Press Enter for stage 3."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "The Bitwarden note"
ask_value NOTE_NAME "Bitwarden note name:" "Harness HCP project inputs" no
matches=$(bw list items --search "$NOTE_NAME" | NAME="$NOTE_NAME" node -e '
  const items = JSON.parse(require("fs").readFileSync(0, "utf8"));
  process.stdout.write(items.filter((i) => i.name === process.env.NAME && i.type === 2).map((i) => i.id).join("\n"));')
NOTE_ID=""
MAP="{}"
case "$(grep -c . <<<"$matches" || true)" in
  0) step "No secure note is named that yet; the wizard will create it." ;;
  1)
    NOTE_ID="$matches"
    MAP=$(bw get item "$NOTE_ID" | jq -c '.notes // "{}" | fromjson | if type == "object" then . else error end' 2>/dev/null) \
      || die "That note's notes aren't a JSON object. Fix or rename it, then re-run."
    step "Found it. Its values are the defaults below; Enter keeps each one."
    ;;
  *) die "More than one secure note is named \"$NOTE_NAME\". Rename all but one, then re-run." ;;
esac
pause "Press Enter for stage 4."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Values for the managed inputs"
say "The map must hold every managed input, or the plan fails on prevent_destroy."
say "HCP can't show stored values, so take each from its custody, not from memory."
say "Every value is typed hidden: even URLs can embed credentials."
if [[ -z "$MANAGED" ]]; then
  note "Nothing managed yet; add inputs in the next stage."
else
  while read -r w c k; do
    say ""
    say "$w · $c · ${BOLD}$k${RESET}"
    hint_for "$w" "$k"
    ask_value value "Value (hidden):" "$(map_get "$w" "$c" "$k")" yes </dev/tty
    [[ -n "$value" ]] || die "$w $c $k can't be empty."
    map_set "$w" "$c" "$k" "$value"
  done <<<"$MANAGED"
fi
value=""
pause "Press Enter for stage 5."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "New inputs"
current_tailnet=$(map_get household-finance terraform tailnet_site_url)
if [[ -z "$current_tailnet" ]]; then
  # Tailscale missing or stopped just means no suggestion, never an exit here.
  detected=$(tailscale status --json 2>/dev/null | jq -r '.Self.DNSName // empty' | sed 's/\.$//') || detected=""
  say "household-finance can take tailnet_site_url, for phone access over Tailscale (#284)."
  if [[ -n "$detected" ]] && confirm "Add tailnet_site_url = https://$detected ?"; then
    map_set household-finance terraform tailnet_site_url "https://$detected"
    step "Added household-finance terraform tailnet_site_url."
  fi
else
  step "household-finance tailnet_site_url is already in the map: $current_tailnet"
fi
while confirm "Add another input?"; do
  ask_value w "Workspace (e.g. household-finance):" "" no
  ask_value c "Category (environment or terraform):" "" no
  ask_value k "Variable name:" "" no
  [[ "$c" == environment || "$c" == terraform ]] || { warn "Category must be environment or terraform."; continue; }
  [[ "$k" =~ ^[A-Za-z_][A-Za-z0-9_]*$ ]] || { warn "Variable names are identifiers."; continue; }
  hint_for "$w" "$k"
  ask_value value "Value (hidden):" "" yes
  [[ -n "$value" ]] || { warn "Empty value; not added."; continue; }
  map_set "$w" "$c" "$k" "$value"
  step "Added $w $c $k."
done
value=""

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Check the map"
missing=$(printf '%s' "$MAP" | MANAGED="$MANAGED" node -e '
  const m = JSON.parse(require("fs").readFileSync(0, "utf8"));
  process.stdout.write(process.env.MANAGED.split("\n").filter(Boolean)
    .filter((a) => { const [w, c, k] = a.split(" "); return !m[w]?.[c]?.[k]; }).join(", "));')
[[ -z "$missing" ]] || die "The map leaves out managed inputs: $missing. Not saved."
step "Every managed input has a value. The map holds (names only):"
printf '%s' "$MAP" | jq -r 'to_entries[] | .key as $w | .value | to_entries[] | .key as $c | .value | keys[] | "\($w)  \($c)  \(.)"' \
  | while read -r line; do note "  $line"; done
pause "Press Enter for stage 7."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Save to Bitwarden"
if [[ -n "$NOTE_ID" ]]; then
  confirm "Replace the notes of \"$NOTE_NAME\" with this map?" || die "Not saved."
  bw get item "$NOTE_ID" | jq --rawfile m <(printf '%s' "$MAP") '.notes = $m' | bw encode | bw edit item "$NOTE_ID" >/dev/null \
    || die "bw edit failed; the note is unchanged."
else
  confirm "Create the secure note \"$NOTE_NAME\" with this map?" || die "Not saved."
  NOTE_ID=$(bw get template item | NAME="$NOTE_NAME" \
    jq --rawfile m <(printf '%s' "$MAP") '.type = 2 | .secureNote = {type: 0} | .name = env.NAME | .notes = $m | .login = null' \
    | bw encode | bw create item | jq -r .id) || die "bw create failed."
fi
saved=$(bw get item "$NOTE_ID" | jq -c '.notes | fromjson')
[[ "$saved" == "$MAP" ]] || die "The saved note doesn't read back as the same map. Check it in Bitwarden."
step "Saved and read back: \"$NOTE_NAME\" holds the map."
pause "Press Enter for stage 8."

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Plan and apply"
say "hcp:projects reads the map through a file descriptor; it never lands on disk"
say "outside the run's temporary mode-0600 tfvars, which it removes afterwards."
step "Planning (scripts/hcp-projects.ts plan)…"
plan=$(node --import tsx scripts/hcp-projects.ts plan --variables-file <(printf '%s' "$MAP") 2>&1 | tee /dev/tty) \
  || die "The plan failed; see its output above. The note is saved, so fix and re-run."
if grep -qE 'will be destroyed|must be replaced|prevent_destroy' <<<"$plan"; then
  die "The plan would destroy or replace something. Not applying; retiring inputs is a separate flow (infrastructure/hcp/README.md)."
fi
updated=$(grep -oE 'tfe_variable\.project_input\[".*"\] will be updated' <<<"$plan" || true)
if [[ -n "$updated" ]]; then
  warn "These stored inputs get the value from the map, replacing what HCP holds:"
  while read -r line; do note "  ${line% will be updated}"; done <<<"$updated"
  warn "HCP can't show the old values. Only continue if each one is meant to change."
fi
if grep -q 'No changes\.' <<<"$plan"; then
  say "Nothing to apply: platform-bootstrap already matches the map."
else
  confirm "Apply? (Terraform plans again and asks for yes)" || die "Not applied. The note is saved."
  node --import tsx scripts/hcp-projects.ts apply --variables-file <(printf '%s' "$MAP") || die "The apply failed; see its output above."
fi
MAP=""

finish
note "Next: plan and apply each changed project workspace's own Terraform root."
[[ "$UNLOCKED_HERE" == yes ]] || note "Bitwarden was already unlocked, so it stays unlocked: bw lock when you're done."
}

run_wizard "$@"; exit
